-- 2THESSALONIANS - HIN Combined
-- Generated: 2026-01-20T22:22:44.847Z

-- c001-v001: Paulos aur Silouanos aur Timotheos –ko kaaliisiyaa Thessalonikayon–ki –mein Parameshwar Pita hamaare aur Prabhu Yeshu Khristos
-- c001-v002: anugrah tumhein aur shaanti –se Parameshwar Pita hamaare aur Prabhu Yeshu Khristos
-- c001-v003: Dhanyavaad–dena chahiye –ko Parameshwar sadaa –ke-baare-mein tumhaare bhaiyo jaise yogya hai ki bahut–badh-raha-hai –the vishwaas tumhaara aur badhta-hai –the prem ek har-ek sab–ka tumhaara –mein ek-doosre
-- c001-v004: taaki hum-khud humein –mein tumhaare-beech garv–karna –mein –ki kaaliisiyaaon –ke Parameshwar –ke-liye –ke dheeraj tumhaare aur vishwaas –mein sab –ke sataaon tumhaare aur –ki kaleeshon jinhe sah-rahe-ho
-- c001-v005: pramaan –ke dharmik nyaay –ke Parameshwar –mein –ke yogya–thahraana tumhein –ke raajya –ke Parameshwar –ke-liye jiske bhi dukh-uthaa-rahe-ho
-- c001-v006: yadi dharmik –ke-paas Parameshwar lauta–dena –ko klesha–dene-waalon tumhein klesha
-- c001-v007: aur tumhein –ko dukh-paane-waalon vishraanti –ke-saath hamaare –mein –ke prakataay –ka Prabhu Yeshu –se swarg –ke-saath dooton shakti–ke unke
-- c001-v008: –mein aag jwaalaa–ki badlaa–lete-hue pratikaara –ko nahin jaanne-waalon Parameshwar aur –ko nahin maanne-waalon –ko susmaachaar –ka Prabhu hamaare Yeshu
-- c001-v009: jo dand bharenge vinaash sanaatan –se mukh –ke Prabhu aur –se –ki mahima –ki shakti unki
-- c001-v010: jab aayega mahima–paana –mein –ke pavitr–logon apne aur ashcharyit–hona –mein sab –ke vishwaas–karne-waalon ki maana–gaya –the gavaahi hamaari –par tumhaare –mein –ke din us
-- c001-v011: –Mein jis bhi praarthana–karte-hain sadaa –ke-liye tumhaare ki tumhein yogya–thahraaye –ke bulaahata –the Parameshwar hamaara aur poori–kare saari prasannataa bhalai–ki aur kaam vishwaas–ka –mein shakti
-- c001-v012: taaki mahimaayit–ho –the naam –ka Prabhu hamaare Yeshu –mein tumhaare-beech aur tum –mein unke –ke-anusaar –ke anugrah –ke Parameshwar hamaare aur Prabhu Yeshu Khristos
-- c002-v001: Nivedan–karte-hain par tumse bhaiyo –ke-liye –ke aagaman –ka Prabhu hamaare Yeshu Khristos aur hamaare ekatra–hona –par unke
-- c002-v002: –mein –ke na jaldi dagmagaana tumhaara –se –ke mann na ghabaraana na –ke-dwaara aatmaa na –ke-dwaara vachan na –ke-dwaara patra jaise –ke-dwaara hamaare ki ki aa–gaya –the din –ka Prabhu
-- c002-v003: na koi tumhein dhokha–de –ke-anusaar kisi-bhi tarah ki yadi na aaye –the vidroh pehle aur prakatit–ho –the manushya –ke adharm –the putr –ke vinaash
-- c002-v004: –the virodh–karne-waala aur apne-aap–ko-ooncha-karne-waala –par sab kahlaaye Parameshwar ya poojya taaki woh –mein –ke mandir –ke Parameshwar baithna dikhaate-hue apne-aap ki hai Parameshwar
-- c002-v005: Nahin yaad–karte-ho ki abhi hote-hue –ke-paas tumhaare ye keh-raha-tha tumhein
-- c002-v006: aur ab –ko rokne-waali jaante-ho –mein –ke prakataaya–jaana usse –mein –ke apne samay
-- c002-v007: –the kyonki bhed pahle–se kaaryasheel–hai –ke adharm keval –the rokne-waala abhi jab–tak –se beech ho–jaaye
-- c002-v008: aur tab prakataaya–jaayega –the adharmee jise –the Prabhu Yeshu maar–dega –se saans –ki mukh apne aur nasht–karega –se prakataay –ke aagaman apne
-- c002-v009: jiska hai –the aagaman –ke-anusaar kaaryashakti –ki Shaitaan –mein saari shakti aur chinhon aur ashcharyon jhoothe
-- c002-v010: aur –mein saare chhal adharm–ke –ko nasht–hone-waalon –ke-badle jis–ka –ko prem –ke satya nahin swiikaar–kiya –mein –ke bachna unka
-- c002-v011: aur –ke-liye is bhejega unhein –the Parameshwar kaaryashakti bhram–ki –mein –ke vishwaas–karna unhein –ko jhooth
-- c002-v012: taaki doshi–thahraaye-jaayein sab –the nahin vishwaas–karne-waale –mein satya balki prasann–hone-waale –mein adharm
-- c002-v013: Hum par chahiye dhanyavaad–dena –ko Parameshwar sadaa –ke-liye tumhaare bhaiyo priye –ke-dwaara Prabhu ki chuna tumhein –ne Parameshwar –se shuruaat –mein udhaar –mein pavitrataa Aatma–ki aur vishwaas satya–mein
-- c002-v014: –mein jis bhi bulaaya tumhein –ke-dwaara –ke susmaachaar hamaare –mein praapti mahima–ki –ka Prabhu hamaare Yeshu Khristos
-- c002-v015: To isliye bhaiyo khade–raho aur pakde–raho –ko shikshaaon jinhe sikhaaye–gaye chaahein –ke-dwaara vachan chaahein –ke-dwaara patra hamaare
-- c002-v016: Swayam par –the Prabhu hamaare Yeshu Khristos aur –the Parameshwar –the Pita hamaare –the prem–karne-waale humein aur dene-waale saantvana sanaatan aur aasha achchhi –mein anugrah
-- c002-v017: saantvana–de tumhaare –ko hridayon aur dridh–kare –mein har kaam aur vachan achchhe
-- c003-v001: –The aur praarthana–karo bhaiyo –ke-liye hamaare ki –the vachan –ka Prabhu daudte-rahe aur mahimaayit–ho jaise bhi –ki-or tumhaare
-- c003-v002: aur ki chutkaara–milein –se –ke galat aur bure manushyon nahin kyonki sab–ka –the vishwaas
-- c003-v003: Vishwaasyogya par hai –the Prabhu jo dridh–karega tumhein aur bachayega –se –ke bure
-- c003-v004: bharosa–hai par –mein Prabhu –par tumhaare ki jo aadesh–dete-hain bhi karte-ho aur karoge
-- c003-v005: –The par Prabhu seedha–kare tumhaare –ko hridayon –mein –ke prem –ka Parameshwar aur –mein –ke dheeraj –ka Khristos
-- c003-v006: Aadesh–dete-hain par tumhein bhaiyo –mein naam –ka Prabhu hamaare Yeshu Khristos door–rehna tumhein –se har bhai belagaam chalne-waale aur nahin –ke-anusaar –ke shikshaa jo paaya –se hamaare
-- c003-v007: tum-khud kyonki jaante-ho kaise chaahiye anukaran–karna hamaara ki nahin belagaam–rahe –mein tumhaare-beech
-- c003-v008: na muft roti khaayi –se kisi balki –mein parishram aur mehanat raat aur din kaam–karte-hue –ke-liye –ke na bhaar–daalna kisi tumhaare
-- c003-v009: nahin ki nahin rakhte adhikaar balki ki apne-aap aadarsh dein tumhein –mein –ke anukaran–karna hamaara
-- c003-v010: aur kyonki jab the –ke-paas tumhaare yahi aadesh–dete-the tumhein ki yadi koi nahin chahta kaam–karna na khaaye
-- c003-v011: sunte-hain kyonki kuchh chalne-waale –mein tumhaare-beech belagaam kuchh-nahin kaam–karne-waale balki duusron–ke-kaam-mein-dakhal–dene-waale
-- c003-v012: –ko par aise aadesh–dete-hain aur protsaahit–karte-hain –mein Prabhu Yeshu Khristos ki –ke-saath shaanti kaam–karte-hue –ko apni roti khaayein
-- c003-v013: Tum par bhaiyo na thako bhalai–karte-hue
-- c003-v014: yadi par koi nahin maane –ko vachan hamaare –ke-dwaara –ke patra usse nishan-lagaao na sangat–rakho usse ki sharminda–ho
-- c003-v015: aur na jaise shatru samjho balki chetaavni–do jaise bhai
-- c003-v016: Swayam par –the Prabhu –ke shaanti de tumhein –ko shaanti –ke-dwaara har –mein har tarah –the Prabhu –ke-saath sab tumhaare
-- c003-v017: –the namaskar –se mere haath Paulos jo hai chinha –mein har patra aise likhta-hoon
-- c003-v018: –the Anugrah –ka Prabhu hamaare Yeshu Khristos –ke-saath sab tumhaare Aameen

